#!/usr/bin/env bash
# W12-1 PPO-0 control (PROTOCOL_CITY_WAVE12_20261006): train PPO-0 signals s1-s5 (CITY_forl --kappa 0, 200 ep) -> KP0-1 -> R_P0 (fleets s213-s513)
# and HUM_P0 on fresh grid4 860-879 (generated by W11) -> report.  SMOKE=1: 2 x 300-s episodes, s1 / s213, seed 860, 600 s, into W12_DIR.
set -o pipefail
cd /Users/phanan/cig-amf-main; export PYTHONHASHSEED=0 OMP_NUM_THREADS=1; PY=external_envs/city_runtime/bin/python
D=${W12_DIR:-research/city_sim/w12_20261006/ppo0}; mkdir -p $D/lights $D/conf $D/check; export XPLAY_TMP=$(cd $D/check && pwd)
P=research/city_sim/spat_pilot_20261004/fleets_v11; RUN="$PY -u scripts/CITY_f1a1_run.py"
if [ "${SMOKE:-0}" = 1 ]; then SM="--smoke"; EP=2; LS="1"; FLS="s213"; CS="860"; else SM=""; EP=200; LS="1 2 3 4 5"; FLS="s213 s313 s413 s513"; CS="$(seq -s ' ' 860 879)"; fi
[ -f research/city_sim/demand/grid4/CONF860_generated ] || { echo "KW12-0 FAIL: 860-879 not generated"; exit 1; }
echo "W12-PPO0 start $(date)"
for s in $LS; do [ -f $D/lights/PPO0_s$s.pt ] || nice -n 5 $PY -u scripts/CITY_forl.py --kappa 0 --seed $s --episodes $EP --name PPO0_s$s --out $D/lights $SM > $D/lights/train_s$s.out 2>&1 & done; wait
for s in $LS; do [ -f $D/lights/PPO0_s$s.pt ] || { echo "PPO-0 training failed s$s"; tail -3 $D/lights/train_s$s.out; exit 1; }; done; echo "PPO-0 lights done $(date)"
# KP0-1: the checkpoint records kappa 0, and a short training episode with kappa 0 yields r_pred == 0 for every decision while misses are counted
$PY - <<PYEOF || { echo "KP0-1 FAIL: stop"; exit 1; }
import sys, torch; sys.path.insert(0, '.')
import scripts.CITY_forl as FO
d = torch.load('$D/lights/PPO0_s1.pt', weights_only=False); assert d['kappa'] == 0.0, d['kappa']
FO.KAPPA = 0.0; net = FO.Net(); info = FO.NetInfo(FO.Q7.NET_S); L = FO.LightFoRL(info, net, train=True, seed=7)
FO.run_episode(FO.Q7.NET_S, FO.Q7.ROU.format(0), 0, L, None, end=300)
rp = [x['r_pred'] for tr in L.traj.values() for x in tr]; print('KP0-1 kappa', d['kappa'], 'decisions', len(rp), 'misses', L.miss, 'max |r_pred|', max(abs(v) for v in rp))
assert len(rp) > 0 and L.miss > 0 and max(abs(v) for v in rp) == 0.0
PYEOF
J=$D/conf_jobs.txt; : > $J
for s in $LS; do echo "HUM_P0_s$s scripts/CITY_eval_forl.py --forl-spat off --light FORL:$D/lights/PPO0_s$s.pt --fleet human" >> $J
  for fl in $FLS; do echo "R_P0_s${s}_${fl} scripts/CITY_eval_forl.py --forl-spat off --light FORL:$D/lights/PPO0_s$s.pt --fleet PL:$P/L11_${fl}_fleet.pt" >> $J; done; done
export PY D RUN SM SS="$CS"
xargs -P 6 -L 1 bash -c 'T=$0; [ -f $D/conf/$T.json ] || nice -n 5 $RUN "$@" --seeds $SS $SM --tag $T --out $D/conf >> $D/conf/run.log 2>&1 || { echo "FAIL $T"; exit 255; }' < $J || { echo "evaluation failure: stop"; exit 1; }
echo "panel done $(date)"
if [ "${SMOKE:-0}" = 1 ]; then W12_SMOKE=$D W12_SEED=860 $PY scripts/CITY_w12_ppo0_report.py; else $PY scripts/CITY_w12_ppo0_report.py; fi || exit 1; echo "W12-PPO0 done $(date)"
